// Spawns a full 360-degree burst of missiles around pUnit using precomputed spread tables (gaRadialBurstMissileSpreadY/X). Iterates 0x40 entries stepping by nStep for the primary ring (velocity from MissileTxt.Param1) and, if nSecondaryCount > 0, a secondary ring of 0x3C entries stepping by nSecondaryCount (velocity from Param2). Copies skill ID and level from the source missile. No-ops for MISSILE_Arrow.
void __fastcall MISSILE_CreateRadialBurst(D2UnitStrc* pUnit, eMissilesId nMissileId, int32_t nSecondaryCount, int32_t nStep, int32_t nSubLoopMult) {
  static int gaRadialBurstMissileSpreadConst2[16] = {0x2, 0x2, 0x2, 0x1, 0x0, -0x1, -0x2, -0x2, -0x2, -0x2, -0x2, -0x1, 0x0, 0x1, 0x2, 0x2};
  D2_STATIC_GUARD(gaRadialBurstMissileSpreadConst2, "D2Client::UNIT::Missile::MISSILE_CreateRadialBurst::gaRadialBurstMissileSpreadConst2");
  static int gaRadialBurstMissileSpreadY[16] = {0x0, 0x1, 0x2, 0x2, 0x2, 0x2, 0x2, 0x1, 0x0, -0x1, -0x2, -0x2, -0x2, -0x2, -0x2, -0x1};
  D2_STATIC_GUARD(gaRadialBurstMissileSpreadY, "D2Client::UNIT::Missile::MISSILE_CreateRadialBurst::gaRadialBurstMissileSpreadY");
  D2MissilesTxt* pMissileTxt;
  D2SkillArgStrc sSkillArg;
  if ((int)nMissileId < 0 || (int)nMissileId >= D2Common::ITEMS::Items::sgptDataTable->nTxtMissilesSize) {
    pMissileTxt = 0;
  } else {
    pMissileTxt = D2Common::ITEMS::Items::sgptDataTable->pTxtMissiles + nMissileId;
  }
  if (nMissileId == MISSILE_Arrow) {
    return;
  }
  memset(&sSkillArg, 0, 0x5c);
  sSkillArg.nFlags = 0x17;
  if (nSubLoopMult > 0) {
    sSkillArg.nFlags = 0x1f;
    sSkillArg.nSubLoopMult = nSubLoopMult;
  }
  sSkillArg.pOwner = CUnit::MISSILE_GetOwnerUnit(pUnit);
  eD2UnitType eUnitType = pUnit->eUnitType;
  sSkillArg.pMissile = pUnit;
  sSkillArg.nMissileTxtNo = nMissileId;
  int nXValue;
  if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
    nXValue = pUnit->pPath.pStaticPath->nPosX;
  } else if (pUnit->pPath.pDynamicPath) {
    nXValue = D2Common::PATH::DynamicPath::GetXPos(pUnit->pPath.pDynamicPath);
  } else {
    nXValue = 0;
  }
  sSkillArg.nX = nXValue;
  eUnitType = pUnit->eUnitType;
  int nYValue;
  if (eUnitType == UNIT_OBJECT || (int)eUnitType > 3 && (int)eUnitType <= 5) {
    nYValue = pUnit->pPath.pStaticPath->nPosY;
  } else if (pUnit->pPath.pDynamicPath) {
    nYValue = D2Common::PATH::DynamicPath::GetYPos(pUnit->pPath.pDynamicPath);
  } else {
    nYValue = 0;
  }
  sSkillArg.nY = nYValue;
  sSkillArg.eSkillNo = D2Common::Units::Missile::GetSkillId(pUnit);
  sSkillArg.nSkillLevel = D2Common::Units::Missile::GetLevel(pUnit);
  sSkillArg.nVelocityOverride = pMissileTxt->Param1 << 7;
  if (nStep < 1) {
    nStep = 1;
  }
  int iSpreadIdx = 0;
  do {
    sSkillArg.nUnitX = *(int*)((char*)gaRadialBurstMissileSpreadY + iSpreadIdx);
    sSkillArg.nUnitY = *(int*)((char*)gaRadialBurstMissileSpreadConst2 + iSpreadIdx);
    Missile::MakeMissile(&sSkillArg);
    iSpreadIdx += nStep * 4;
  } while (iSpreadIdx < 0x40);
  if (nSecondaryCount <= 0) {
    return;
  }
  sSkillArg.nVelocityOverride = pMissileTxt->Param2 << 7;
  iSpreadIdx = 0;
  do {
    sSkillArg.nUnitX = *(int*)((char*)gaRadialBurstMissileSpreadY + iSpreadIdx + 4);
    sSkillArg.nUnitY = *(int*)((char*)gaRadialBurstMissileSpreadConst2 + iSpreadIdx + 4);
    Missile::MakeMissile(&sSkillArg);
    iSpreadIdx += nSecondaryCount * 4;
  } while (iSpreadIdx < 0x3c);
}

// Client-side missile hit handler #030: on impact, spawns a fan of CltHitSubMissile1 sub-missiles from the parent missile. Validates pUnit and its missiles.txt row, requires CltHitSubMissile1 set and a resolvable owner. Builds a D2SkillArgStrc (owner/skill/level from the parent missile, txtno=CltHitSubMissile1) and iterates the global Clt030 X/Y spread tables in steps of cHitPar1 (min 1) up to 64 entries; for each MakeMissile call it also seeds the sub-missile's TargetX/TargetY from the spread offset. Always returns 1. __fastcall: pUnit(ECX), pTarget(EDX). pTarget is unused.
