  D2_STATIC_GUARD(gaSubMissileSpreadY_Clt030, "D2Client::UNIT::Missile::MISSILE_CltHitFn30_FrozenOrb::gaSubMissileSpreadY_Clt030");
  static int gaSubMissileSpreadX_Clt030[64] = {0x1e, 0x1d, 0x1d, 0x1c, 0x1b, 0x1a, 0x18, 0x17, 0x15, 0x13, 0x10, 0xe, 0xb, 0x8, 0x5, 0x2, 0x0, -0x2, -0x5, -0x8, -0xb, -0xe, -0x10, -0x13, -0x15, -0x17, -0x18, -0x1a, -0x1b, -0x1c, -0x1d, -0x1d, -0x1e, -0x1d, -0x1d, -0x1c, -0x1b, -0x1a, -0x18, -0x17, -0x15, -0x13, -0x10, -0xe, -0xb, -0x8, -0x5, -0x2, 0x0, 0x2, 0x5, 0x8, 0xb, 0xe, 0x10, 0x13, 0x15, 0x17, 0x18, 0x1a, 0x1b, 0x1c, 0x1d, 0x1d};
  D2_STATIC_GUARD(gaSubMissileSpreadX_Clt030, "D2Client::UNIT::Missile::MISSILE_CltHitFn30_FrozenOrb::gaSubMissileSpreadX_Clt030");
  D2UnitStrc* pOwnerUnit;
  D2UnitStrc* pSubMissile;
  int nSpreadOffset;
  int nClassId;
  D2SkillArgStrc sSkillArg;
  if (pUnit) {
    D2MissilesTxt* pMissileTxt;
    nClassId = pUnit->nClassId;
    pMissileTxt = nClassId >= 0 && nClassId < D2Common::ITEMS::Items::sgptDataTable->nTxtMissilesSize ? D2Common::ITEMS::Items::sgptDataTable->pTxtMissiles + nClassId : nullptr;
    if (pMissileTxt && pMissileTxt->CltHitSubMissile1 >= 0) {
      pOwnerUnit = CUnit::MISSILE_GetOwnerUnit(pUnit);
      if (!pOwnerUnit) {
        return 1;
      }
      memset(&sSkillArg, 0, 0x5c);
      sSkillArg.nFlags = 2;
      sSkillArg.pOwner = pOwnerUnit;
      sSkillArg.pMissile = pUnit;
      sSkillArg.eSkillNo = D2Common::Units::Missile::GetSkillId(pUnit);
      sSkillArg.nSkillLevel = D2Common::Units::Missile::GetLevel(pUnit);
      sSkillArg.nMissileTxtNo = (eMissilesId)pMissileTxt->CltHitSubMissile1;
      nClassId = pMissileTxt->cHitPar1;
      if (nClassId < 1) {
        nClassId = 1;
      }
      nSpreadOffset = 0;
      do {
        sSkillArg.nUnitX = *(int*)((char*)gaSubMissileSpreadX_Clt030 + nSpreadOffset);
        sSkillArg.nUnitY = *(int*)((char*)gaSubMissileSpreadY_Clt030 + nSpreadOffset);
        pSubMissile = Missile::MakeMissile(&sSkillArg);
        if (pSubMissile) {
          D2Common::Units::Missile::SetTargetX(pSubMissile, *(int32_t*)((char*)gaSubMissileSpreadX_Clt030 + nSpreadOffset));
          D2Common::Units::Missile::SetTargetY(pSubMissile, *(int32_t*)((char*)gaSubMissileSpreadY_Clt030 + nSpreadOffset));
        }
        nSpreadOffset += nClassId * 4;
      } while (nSpreadOffset < 0x100);
      return 1;
    }
  }
  return 1;
}

