// Server-side missile hit-function: on the missile's first frame only (CurrentFrame==0), spawns a fan of HitSubMissile1 child missiles in a fixed spread around the impact, stepping through the static spread X/Y offset tables (gaSubMissileSpread*_Srv029) with stride sHitPar1. Each child is created via CreatingMissile and given the spread offset as its target direction. Returns 2 if invoked on a later frame (no-op), 3 after spawning, 1 if missile/owner invalid or HitSubMissile1<0.
BOOL __fastcall Missiles_SrvHitFunc_SpawnSpreadSubMissilesOnFirstFrame(::SGAMEDATA* pGame, D2UnitStrc* pUnit, D2UnitStrc* pTarget) {
  static int gaSubMissileSpreadY_Srv029[64] = {0x0, 0x2, 0x5, 0x8, 0xb, 0xe, 0x10, 0x13, 0x15, 0x17, 0x18, 0x1a, 0x1b, 0x1c, 0x1d, 0x1d, 0x1e, 0x1d, 0x1d, 0x1c, 0x1b, 0x1a, 0x18, 0x17, 0x15, 0x13, 0x10, 0xe, 0xb, 0x8, 0x5, 0x2, 0x0, -0x2, -0x5, -0x8, -0xb, -0xe, -0x10, -0x13, -0x15, -0x17, -0x18, -0x1a, -0x1b, -0x1c, -0x1d, -0x1d, -0x1e, -0x1d, -0x1d, -0x1c, -0x1b, -0x1a, -0x18, -0x17, -0x15, -0x13, -0x10, -0xe, -0xb, -0x8, -0x5, -0x2};
  D2_STATIC_GUARD(gaSubMissileSpreadY_Srv029, "D2Game::MISSILES::MissilesMode::Missiles_SrvHitFunc_SpawnSpreadSubMissilesOnFirstFrame::gaSubMissileSpreadY_Srv029");
  static int gaSubMissileSpreadX_Srv029[64] = {0x1e, 0x1d, 0x1d, 0x1c, 0x1b, 0x1a, 0x18, 0x17, 0x15, 0x13, 0x10, 0xe, 0xb, 0x8, 0x5, 0x2, 0x0, -0x2, -0x5, -0x8, -0xb, -0xe, -0x10, -0x13, -0x15, -0x17, -0x18, -0x1a, -0x1b, -0x1c, -0x1d, -0x1d, -0x1e, -0x1d, -0x1d, -0x1c, -0x1b, -0x1a, -0x18, -0x17, -0x15, -0x13, -0x10, -0xe, -0xb, -0x8, -0x5, -0x2, 0x0, 0x2, 0x5, 0x8, 0xb, 0xe, 0x10, 0x13, 0x15, 0x17, 0x18, 0x1a, 0x1b, 0x1c, 0x1d, 0x1d};
  D2_STATIC_GUARD(gaSubMissileSpreadX_Srv029, "D2Game::MISSILES::MissilesMode::Missiles_SrvHitFunc_SpawnSpreadSubMissilesOnFirstFrame::gaSubMissileSpreadX_Srv029");
  int nLoopOffset;
  D2SkillArgStrc sSkillArg;
  int nClassId;
  D2MissilesTxt* pMissileTxt = pUnit && (nClassId = pUnit->nClassId) >= 0 && nClassId < D2Common::ITEMS::Items::sgptDataTable->nTxtMissilesSize ? D2Common::ITEMS::Items::sgptDataTable->pTxtMissiles + nClassId : nullptr;
  if (!(pMissileTxt && pMissileTxt->HitSubMissile1 >= 0)) {
    return 1;
  }
  int32_t nCurrFrame = D2Common::Units::Missile::GetCurrentFrame(pUnit);
  if (nCurrFrame) {
    return 2;
  }
  D2UnitStrc* pOwnerUnit = UNIT::SUnit::GetOwnerUnit(pGame, pUnit);
  if (pOwnerUnit) {
    D2UnitStrc* pUnit_00;
    memset(&sSkillArg, 0, 0x5c);
    sSkillArg.nFlags = 2;
    sSkillArg.pOwner = pOwnerUnit;
    sSkillArg.pMissile = pUnit;
    sSkillArg.eSkillNo = D2Common::Units::Missile::GetSkillId(pUnit);
    sSkillArg.nSkillLevel = D2Common::Units::Missile::GetLevel(pUnit);
    sSkillArg.nMissileTxtNo = (eMissilesId)pMissileTxt->HitSubMissile1;
    nClassId = pMissileTxt->sHitPar1;
    if (nClassId < 1) {
      nClassId = 1;
    }
    nLoopOffset = 0;
    do {
      sSkillArg.nUnitX = *(int*)((char*)gaSubMissileSpreadX_Srv029 + nLoopOffset);
      sSkillArg.nUnitY = *(int*)((char*)gaSubMissileSpreadY_Srv029 + nLoopOffset);
      pUnit_00 = Missiles::CreatingMissile(pGame, &sSkillArg);
      if (pUnit_00) {
        D2Common::Units::Missile::SetTargetX(pUnit_00, *(int32_t*)((char*)gaSubMissileSpreadX_Srv029 + nLoopOffset));
        D2Common::Units::Missile::SetTargetY(pUnit_00, *(int32_t*)((char*)gaSubMissileSpreadY_Srv029 + nLoopOffset));
      }
      nLoopOffset += nClassId * 4;
    } while (nLoopOffset < 0x100);
    return 3;
  }
  return 1;
}

