// Server skill handler for Fire Ring (8-direction). Validates skill/missile txt records, sets UNITFLAG_SKSRVDOFUNC, then spawns two rings of missiles (inner and outer) at evenly spaced cardinal/diagonal offsets around the caster using calc[0] as damage/speed override and calc[1] as the second-ring missile count. Returns TRUE on success.
BOOL __fastcall Skills_SrvDoFunc_099_FireMissileRing8Dir(::SGAMEDATA* pGame, D2UnitStrc* pUnit, eD2Skills eSkill, int32_t nSkillLvl) {
  static int gnSkillMissileCount_FireOrb[16] = {0x2, 0x2, 0x2, 0x1, 0x0, -0x1, -0x2, -0x2, -0x2, -0x2, -0x2, -0x1, 0x0, 0x1, 0x2, 0x2};
  D2_STATIC_GUARD(gnSkillMissileCount_FireOrb, "D2Game::SKILLS::SkillMonst::Skills_SrvDoFunc_099_FireMissileRing8Dir::gnSkillMissileCount_FireOrb");
  static int gnSkillMissileCount_FireRing[16] = {0x0, 0x1, 0x2, 0x2, 0x2, 0x2, 0x2, 0x1, 0x0, -0x1, -0x2, -0x2, -0x2, -0x2, -0x2, -0x1};
  D2_STATIC_GUARD(gnSkillMissileCount_FireRing, "D2Game::SKILLS::SkillMonst::Skills_SrvDoFunc_099_FireMissileRing8Dir::gnSkillMissileCount_FireRing");
  D2MissilesTxt* pMissileTxt;
  int nDirIndex;
  D2SkillArgStrc sSkillArg;
  D2SkillsTxt* pSkillsTxt = (int)eSkill >= 0 && (int)eSkill < D2Common::ITEMS::Items::sgptDataTable->nTxtSkillsCount ? D2Common::ITEMS::Items::sgptDataTable->pTxtSkills + eSkill : nullptr;
  if (!pSkillsTxt) {
    return 0;
  }
  eMissilesId eSrvMissileId = (eMissilesId)pSkillsTxt->srvmissile[1];
  pMissileTxt = (int)eSrvMissileId >= 0 && (int)eSrvMissileId < D2Common::ITEMS::Items::sgptDataTable->nTxtMissilesSize ? D2Common::ITEMS::Items::sgptDataTable->pTxtMissiles + eSrvMissileId : nullptr;
  if (pMissileTxt) {
    int32_t nMissileCount;
    if (pUnit) {
      pUnit->eUnitFlags |= UNITFLAG_SKSRVDOFUNC;
    }
    memset(&sSkillArg, 0, 0x5c);
    sSkillArg.nFlags = 0x1f;
    sSkillArg.pOwner = pUnit;
    sSkillArg.pMissile = pUnit;
    sSkillArg.nMissileTxtNo = eSrvMissileId;
    sSkillArg.nX = D2Common::Units::GetXPosFromDynamicPathUnit(pUnit);
    sSkillArg.nY = D2Common::Units::GetYPosFromDynamicPathUnit(pUnit);
    sSkillArg.nSkillLevel = nSkillLvl;
    sSkillArg.nSubLoopMult = D2Common::Skills::D2GetSkillCalc(pUnit, pSkillsTxt->calc[0], eSkill, nSkillLvl);
    sSkillArg.nVelocityOverride = pMissileTxt->Param1 << 6;
    nMissileCount = D2Common::Skills::D2GetSkillCalc(pUnit, pSkillsTxt->calc[1], eSkill, nSkillLvl);
    if (nMissileCount < 1) {
      nMissileCount = 1;
    }
    nDirIndex = 0;
    do {
      sSkillArg.nUnitX = *(int*)((char*)gnSkillMissileCount_FireRing + nDirIndex);
      sSkillArg.nUnitY = *(int*)((char*)gnSkillMissileCount_FireOrb + nDirIndex);
      MISSILES::Missiles::CreatingMissile(pGame, &sSkillArg);
      nDirIndex += 8;
    } while (nDirIndex < 0x40);
    sSkillArg.nVelocityOverride = pMissileTxt->Param2 << 6;
    if (nMissileCount <= 1) {
      return 1;
    }
    nDirIndex = 0;
    do {
      sSkillArg.nUnitX = *(int*)((char*)gnSkillMissileCount_FireRing + nDirIndex + 4);
      sSkillArg.nUnitY = *(int*)((char*)gnSkillMissileCount_FireOrb + nDirIndex + 4);
      MISSILES::Missiles::CreatingMissile(pGame, &sSkillArg);
      nDirIndex += nMissileCount * 4;
    } while (nDirIndex < 0x3c);
    return 1;
  }
  return 0;
}

